fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    let off = offset % n;
    let mut b = Vec::with_capacity(n);

    for i in 0..n {
        let j = (i + off) % n;
        b.push(a[j]);
    }

    b
}